namespace sv_3cffd44d9c2a439aa85693b3fd47e63f.Services;

public class AppointmentService
{
    private static readonly List<string> Doctors =
    [
        "Dr. Smith",
        "Dr. Johnson",
        "Dr. Patel",
        "Dr. Williams"
    ];

    private static readonly List<string> TimeSlots =
    [
        "9:00 AM",
        "9:30 AM",
        "10:00 AM",
        "10:30 AM",
        "11:00 AM",
        "1:00 PM",
        "1:30 PM",
        "2:00 PM",
        "2:30 PM",
        "3:00 PM"
    ];

    public Task<List<string>> GetDoctorsAsync()
    {
        return Task.FromResult(Doctors);
    }

    public Task<List<string>> GetAvailableTimeSlotsAsync(string doctor, DateOnly date)
    {
        // Simulate fewer slots for certain doctors/dates
        var slots = date.DayOfWeek switch
        {
            DayOfWeek.Saturday or DayOfWeek.Sunday => TimeSlots.Take(4).ToList(),
            _ => TimeSlots.ToList()
        };

        return Task.FromResult(slots);
    }

    /// <summary>
    /// Validates patient and appointment details against server-side business rules.
    /// Returns a dictionary of field name → error messages. Empty means valid.
    /// </summary>
    public Task<Dictionary<string, List<string>>> ValidatePatientAsync(
        string email,
        string insuranceProvider,
        string doctor,
        string timeSlot)
    {
        var errors = new Dictionary<string, List<string>>();

        // Rule: email with outstanding balance
        if (string.Equals(email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            errors[nameof(AppointmentModel.Email)] = ["Account has outstanding balance"];
        }

        // Rule: "None" insurance with a doctor who doesn't accept self-pay
        if (string.Equals(insuranceProvider, "None", StringComparison.Ordinal)
            && string.Equals(doctor, "Dr. Smith", StringComparison.Ordinal))
        {
            errors[nameof(AppointmentModel.Doctor)] = ["Selected doctor does not accept self-pay patients"];
        }

        // Rule: time slot race condition
        if (string.Equals(timeSlot, "10:00 AM", StringComparison.Ordinal))
        {
            errors[nameof(AppointmentModel.TimeSlot)] = ["This slot is no longer available"];
        }

        return Task.FromResult(errors);
    }
}

using System.ComponentModel.DataAnnotations;

namespace sv_3cffd44d9c2a439aa85693b3fd47e63f.Services;

public class AppointmentModel
{
    // Step 1
    [Required(ErrorMessage = "Patient name is required.")]
    [Display(Name = "Patient Name")]
    public string? PatientName { get; set; }

    [Required(ErrorMessage = "Email is required.")]
    [EmailAddress(ErrorMessage = "Enter a valid email address.")]
    public string? Email { get; set; }

    [Required(ErrorMessage = "Phone number is required.")]
    [Phone(ErrorMessage = "Enter a valid phone number.")]
    public string? Phone { get; set; }

    [Required(ErrorMessage = "Please select an insurance provider.")]
    [Display(Name = "Insurance Provider")]
    public string? InsuranceProvider { get; set; }

    // Step 2
    [Required(ErrorMessage = "Please select a doctor.")]
    public string? Doctor { get; set; }

    [Required(ErrorMessage = "Date is required.")]
    [FutureDate(ErrorMessage = "Date must be in the future.")]
    public DateOnly? Date { get; set; }

    [Required(ErrorMessage = "Please select a time slot.")]
    [Display(Name = "Time Slot")]
    public string? TimeSlot { get; set; }

    [Required(ErrorMessage = "Reason for visit is required.")]
    [StringLength(500, ErrorMessage = "Reason must be 500 characters or fewer.")]
    [Display(Name = "Reason for Visit")]
    public string? ReasonForVisit { get; set; }
}

public class FutureDateAttribute : ValidationAttribute
{
    public override bool IsValid(object? value)
    {
        if (value is DateOnly date)
        {
            return date > DateOnly.FromDateTime(DateTime.Today);
        }
        return true; // Let [Required] handle nulls
    }
}

