@page "/book-appointment"
@rendermode InteractiveServer
@using sv_3cffd44d9c2a439aa85693b3fd47e63f.Services
@inject AppointmentService AppointmentService

<PageTitle>Book Appointment</PageTitle>

<h3>Book an Appointment</h3>

<EditForm EditContext="editContext" OnValidSubmit="HandleSubmit">
    <DataAnnotationsValidator />
    <ServerFieldValidator @ref="serverValidator" />

    <fieldset>
        <legend>Patient Information</legend>

        <div class="mb-3">
            <label class="form-label" for="patientName">Patient Name</label>
            <InputText id="patientName" class="form-control" @bind-Value="Model.PatientName" />
            <ValidationMessage For="() => Model.PatientName" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="email">Email</label>
            <InputText id="email" class="form-control" @bind-Value="Model.Email" />
            <ValidationMessage For="() => Model.Email" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="phone">Phone</label>
            <InputText id="phone" class="form-control" @bind-Value="Model.Phone" />
            <ValidationMessage For="() => Model.Phone" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="insurance">Insurance Provider</label>
            <InputSelect id="insurance" class="form-select" @bind-Value="Model.InsuranceProvider">
                <option value="">-- Select --</option>
                <option value="Aetna">Aetna</option>
                <option value="BlueCross">BlueCross</option>
                <option value="Cigna">Cigna</option>
                <option value="UnitedHealth">UnitedHealth</option>
                <option value="None">None</option>
            </InputSelect>
            <ValidationMessage For="() => Model.InsuranceProvider" />
        </div>
    </fieldset>

    @if (!showStep2)
    {
        <button type="button" class="btn btn-primary" @onclick="ProceedToStep2" disabled="@isProcessing">
            @(isProcessing ? "Checking..." : "Next")
        </button>
    }

    @if (showStep2)
    {
        <fieldset class="mt-4">
            <legend>Appointment Details</legend>

            <div class="mb-3">
                <label class="form-label" for="doctor">Preferred Doctor</label>
                <InputSelect id="doctor" class="form-select" @bind-Value="Model.Doctor">
                    <option value="">-- Select --</option>
                    @foreach (var doctor in doctors)
                    {
                        <option value="@doctor">@doctor</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.Doctor" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="date">Date</label>
                <InputDate id="date" class="form-control" @bind-Value="Model.Date" @bind:after="OnDateChanged" />
                <ValidationMessage For="() => Model.Date" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="timeslot">Time Slot</label>
                <InputSelect id="timeslot" class="form-select" @bind-Value="Model.TimeSlot">
                    <option value="">-- Select --</option>
                    @foreach (var slot in timeSlots)
                    {
                        <option value="@slot">@slot</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.TimeSlot" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="reason">Reason for Visit</label>
                <InputTextArea id="reason" class="form-control" rows="3" @bind-Value="Model.ReasonForVisit" />
                <ValidationMessage For="() => Model.ReasonForVisit" />
            </div>

            <div class="d-flex gap-2">
                <button type="button" class="btn btn-outline-secondary" @onclick="BackToStep1">
                    Back
                </button>
                <button type="button" class="btn btn-warning" @onclick="CheckAvailability" disabled="@isProcessing">
                    @(isProcessing ? "Checking..." : "Check Availability")
                </button>
                <button type="submit" class="btn btn-success" disabled="@(isProcessing || !availabilityConfirmed)">
                    Book Appointment
                </button>
            </div>
        </fieldset>
    }
</EditForm>

@if (bookingConfirmed)
{
    <div class="alert alert-success mt-4" role="alert">
        Appointment booked successfully for <strong>@Model.PatientName</strong>
        with <strong>@Model.Doctor</strong> on @Model.Date?.ToString("MMMM d, yyyy")
        at @Model.TimeSlot.
    </div>
}

@code {
    private AppointmentModel Model { get; set; } = new();
    private EditContext editContext = default!;
    private ServerFieldValidator? serverValidator;

    private List<string> doctors = [];
    private List<string> timeSlots = [];
    private bool showStep2;
    private bool isProcessing;
    private bool availabilityConfirmed;
    private bool bookingConfirmed;

    private static readonly string[] Step1Fields =
        [nameof(AppointmentModel.PatientName), nameof(AppointmentModel.Email),
         nameof(AppointmentModel.Phone), nameof(AppointmentModel.InsuranceProvider)];

    protected override async Task OnInitializedAsync()
    {
        editContext = new EditContext(Model);
        doctors = await AppointmentService.GetDoctorsAsync();
    }

    private bool ValidateStep1()
    {
        editContext.Validate();
        foreach (var field in Step1Fields)
        {
            if (editContext.GetValidationMessages(editContext.Field(field)).Any())
                return false;
        }
        return true;
    }

    private void ProceedToStep2()
    {
        if (ValidateStep1())
        {
            showStep2 = true;
        }
    }

    private void BackToStep1()
    {
        showStep2 = false;
        availabilityConfirmed = false;
    }

    private async Task OnDateChanged()
    {
        Model.TimeSlot = null;
        availabilityConfirmed = false;

        if (Model.Date.HasValue && !string.IsNullOrEmpty(Model.Doctor))
        {
            timeSlots = await AppointmentService.GetAvailableTimeSlotsAsync(Model.Doctor, Model.Date.Value);
        }
    }

    private async Task CheckAvailability()
    {
        serverValidator?.ClearErrors();
        availabilityConfirmed = false;

        if (!editContext.Validate())
            return;

        isProcessing = true;
        try
        {
            var errors = await AppointmentService.ValidatePatientAsync(
                Model.Email!,
                Model.InsuranceProvider!,
                Model.Doctor!,
                Model.TimeSlot!);

            if (errors.Count > 0)
            {
                serverValidator!.DisplayErrors(errors);
            }
            else
            {
                availabilityConfirmed = true;
            }
        }
        finally
        {
            isProcessing = false;
        }
    }

    private async Task HandleSubmit()
    {
        if (!availabilityConfirmed)
            return;

        isProcessing = true;
        try
        {
            await Task.Delay(500); // Simulate booking
            bookingConfirmed = true;
        }
        finally
        {
            isProcessing = false;
        }
    }
}

using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Forms;

namespace sv_3cffd44d9c2a439aa85693b3fd47e63f.Components.Pages;

public class ServerFieldValidator : ComponentBase
{
    [CascadingParameter]
    private EditContext? EditContext { get; set; }

    private ValidationMessageStore? messageStore;

    protected override void OnInitialized()
    {
        messageStore = new ValidationMessageStore(EditContext!);
        EditContext!.OnValidationRequested += (s, e) => messageStore.Clear();
        EditContext!.OnFieldChanged += (s, e) => messageStore.Clear(e.FieldIdentifier);
    }

    public void DisplayErrors(Dictionary<string, List<string>> errors)
    {
        foreach (var (field, messages) in errors)
        {
            foreach (var message in messages)
            {
                messageStore!.Add(EditContext!.Field(field), message);
            }
        }
        EditContext!.NotifyValidationStateChanged();
    }

    public void ClearErrors()
    {
        messageStore?.Clear();
        EditContext?.NotifyValidationStateChanged();
    }
}

