    {
        Model.TimeSlot = null;
        availabilityConfirmed = false;

        if (Model.Date.HasValue && !string.IsNullOrEmpty(Model.Doctor))
        {
            timeSlots = await AppointmentService.GetAvailableTimeSlotsAsync(Model.Doctor, Model.Date.Value);
        }
    }

