    {
        serverValidator?.ClearErrors();
        availabilityConfirmed = false;

        if (!editContext.Validate())
            return;

        isProcessing = true;
        try
        {
            var errors = await AppointmentService.ValidatePatientAsync(
                Model.Email!,
                Model.InsuranceProvider!,
                Model.Doctor!,
                Model.TimeSlot!);

            if (errors.Count > 0)
            {
                serverValidator!.DisplayErrors(errors);
            }
            else
            {
                availabilityConfirmed = true;
            }
        }
        finally
        {
            isProcessing = false;
        }
    }

    private async Task HandleSubmit()
    {
        if (!availabilityConfirmed)
            return;

        isProcessing = true;
        try
        {
            await Task.Delay(500); // Simulate booking
            bookingConfirmed = true;
        }
        finally
        {
            isProcessing = false;
        }
    }
}

